  const today=()=>new Date().toISOString().slice(0,10),isoOffset=days=>new Date(Date.now()+days*86400000).toISOString(),fmt=n=>Number(n||0).toLocaleString('ko-KR');
  const deviceZone=Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',scheduleZone=()=>F.v38Account?.locale.timezone||deviceZone;
  function zonedParts(epoch,zone){const p=Object.fromEntries(new Intl.DateTimeFormat('sv-SE',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(epoch)).map(x=>[x.type,x.value]));return {date:p.year+'-'+p.month+'-'+p.day,time:p.hour+':'+p.minute};}
  function zonedEpoch(date,time,zone){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^\d{2}:\d{2}$/.test(time))return NaN;const [y,m,d]=date.split('-').map(Number),[hh,mm]=time.split(':').map(Number),target=Date.UTC(y,m-1,d,hh,mm);let at=target;for(let i=0;i<3;i++){const p=zonedParts(at,zone),[a,b,c]=p.date.split('-').map(Number),[h,n]=p.time.split(':').map(Number);at=target-(Date.UTC(a,b-1,c,h,n)-at);}const check=zonedParts(at,zone);return check.date===date&&check.time===time?at:NaN;}
  const scheduleAt=r=>Number.isFinite(r.at)?r.at:zonedEpoch(r.date,r.time,r.timezone||deviceZone);
