    recordings:Array.from({length:65},(_,i)=>({id:'recording-'+i,title:`${isoOffset(-i).slice(0,10)}_${i%3?'함께하는 작업':'긴 방송 제목과 작업 과정 정리'}.mp4`,createdAt:isoOffset(-i),duration:8076-i*20,size:Math.max(.2,7.8-i*.08),status:i===3?'누락':i===6?'손상':i===9?'녹화 중':'완료',deleted:false})),
