  const role=()=>F.v38Access.role||'owner';
  function allowed(cap,id=F.currentBase){if(id==='policy'&&cap==='view')return true;if(!F.sessionLoggedIn)return false;if(typeof F.v38Access.can==='function')return F.v38Access.can(service.has(id)?'service-admin':cap,id);return service.has(id)?role()==='service-admin':role()!=='viewer';}
  const capFor=action=>action.startsWith('key-')?'keys':action.startsWith('moderator-')?'members':'edit';
  const b=(label,action,attrs='',cls='')=>F.btn(label,'v38-manage-'+action,'',cls,attrs+((action.startsWith('moderator-')||action.startsWith('key-'))&&!allowed(capFor(action))?' disabled':''));
  const input=(label,name,value='',attrs='')=>`<div class="field"><label for="v38-m-${name}">${e(label)}</label><input id="v38-m-${name}" name="${name}" value="${e(value)}" ${attrs}></div>`;
  const area=(label,name,value='',attrs='')=>`<div class="field"><label for="v38-m-${name}">${e(label)}</label><textarea id="v38-m-${name}" name="${name}" rows="3" ${attrs}>${e(value)}</textarea></div>`;
  const choice=(label,name,value,items)=>`<div class="field"><label for="v38-m-${name}">${e(label)}</label><button type="button" id="v38-m-${name}" data-action="v38-manage-choice" data-name="${name}" data-options="${e(JSON.stringify(items))}" class="choice-button" aria-label="${e(label)}" aria-haspopup="listbox" aria-expanded="false"><span>${e(value)}</span>${F.icon('chevron')}</button><input type="hidden" name="${name}" value="${e(value)}"></div>`;
  const fieldData=form=>Object.fromEntries([...new FormData(form)].map(([key,value])=>[key,String(value).trim()]));
  const toggle=(label,key,on,action='moderation-toggle')=>F.setting(label,'',`<button type="button" class="switch" role="switch" aria-label="${e(label)}" aria-checked="${on}" data-action="v38-manage-${action}" data-key="${key}"><span class="switch-track"></span></button>`);
  const empty=title=>F.empty(title,'','');
