  const badge=status=>F.pill(e(status),['완료','성공','정상','답변 완료','수신 중'].includes(status)?'green':['실패','손상','장애','오류'].includes(status)?'red':'orange');
  function decorate(html,id){const h=document.createElement('div');h.innerHTML=html;const page=h.querySelector('.content-page')||h.firstElementChild;page?.classList.add('v33-management','v38-management');if(page)page.dataset.v38Screen=id;return h.innerHTML;}
  function page(title,body,actions='',id=F.currentBase){return decorate(F.page(title,body,actions),id);}
