  function tab(id,items){const current=S.tabs[id]||items[0];return `<div class="page-tabs v38-manage-tabs" role="tablist" aria-label="목록 종류">${items.map((name,i)=>`<button type="button" role="tab" id="v38-tab-${id}-${i}" aria-controls="v38-panel-${id}" aria-selected="${current===name}" tabindex="${current===name?0:-1}" data-action="v38-manage-tab" data-screen="${id}" data-value="${e(name)}" class="${current===name?'active':''}">${e(name)}</button>`).join('')}</div>`;}
  function table(headers,rows){return `<div class="table-panel"><div class="table-scroll"><table><caption class="sr-only">관리 목록</caption><thead><tr>${headers.map(h=>`<th scope="col">${e(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((value,i)=>`<td data-label="${e(headers[i])}">${value}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
  const ls=id=>S.lists[id]||=( {q:'',status:'전체',sort:'최신순',from:'',to:'',page:0} );
  function selectedRows(id,rows){const state=ls(id),tokens=state.q.normalize('NFKC').toLowerCase().split(/\s+/).filter(Boolean);return rows.filter(r=>(state.status==='전체'||r.status===state.status)&&(!state.from||String(r.createdAt||'').slice(0,10)>=state.from)&&(!state.to||String(r.createdAt||'').slice(0,10)<=state.to)&&tokens.every(t=>JSON.stringify(r).normalize('NFKC').toLowerCase().includes(t))).sort((a,b)=>state.sort==='이름순'?String(a.title||a.name||a.who).localeCompare(String(b.title||b.name||b.who),'ko'):state.sort==='오래된순'?String(a.createdAt).localeCompare(String(b.createdAt)):String(b.createdAt).localeCompare(String(a.createdAt))||a.id.localeCompare(b.id));}
  function list(id,rows,headers,row,statuses=[]){const state=ls(id),all=selectedRows(id,rows),max=Math.max(0,Math.ceil(all.length/20)-1);state.page=Math.min(state.page,max);const slice=all.slice(state.page*20,state.page*20+20);const toolbar=`<form class="v38-list-tools" data-v38-search="${id}"><label class="sr-only" for="v38-search-${id}">목록 검색</label><input id="v38-search-${id}" name="query" type="search" maxlength="120" placeholder="이름이나 내용 검색" value="${e(state.q)}"><button type="submit">검색</button>${b('초기화','list-reset',`data-screen="${id}"`,'ghost')}${statuses.length?b(e(state.status)+F.icon('chevron'),'list-status',`data-screen="${id}" data-options="${e(JSON.stringify(['전체',...statuses]))}" aria-label="상태 필터" aria-haspopup="listbox"`,'choice-button'):''}${b(e(state.sort)+F.icon('chevron'),'list-sort',`data-screen="${id}" aria-label="목록 정렬" aria-haspopup="listbox"`,'choice-button')}<label class="v38-date-filter">시작일<input type="date" name="from" value="${e(state.from)}"></label><label class="v38-date-filter">종료일<input type="date" name="to" value="${e(state.to)}"></label></form>`;
    return toolbar+(S.fault==='load:'+id?`${empty('목록을 불러오지 못했어요.')}<div class="form-actions">${b('다시 시도','list-retry',`data-screen="${id}"`)}</div>`:slice.length?table(headers,slice.map(row)):empty(state.q||state.from||state.to||state.status!=='전체'?'조건에 맞는 항목이 없어요.':'등록된 항목이 없어요.'))+`<div class="v38-list-footer"><span role="status">${all.length?state.page*20+1:0}–${Math.min(state.page*20+20,all.length)} / ${fmt(all.length)}개</span><div>${b('이전','list-page',`data-screen="${id}" data-page="${state.page-1}" ${state.page===0?'disabled':''}`)}${b('다음','list-page',`data-screen="${id}" data-page="${state.page+1}" ${state.page===max?'disabled':''}`)}</div></div>`+(state.error?`<div class="v38-page-error" role="alert">다음 목록을 불러오지 못했어요.${b('다시 시도','list-page',`data-screen="${id}" data-page="${state.pending}"`)}</div>`:'');}
  function focusSelector(node){if(!node)return '';if(node.dataset?.action)return `[data-action="${node.dataset.action}"]`+(node.dataset.id?`[data-id="${node.dataset.id}"]`:'');if(node.id)return '#'+CSS.escape(node.id);return '';}
  function refresh(selector){const restore=selector||focusSelector(document.activeElement);F.render();if(restore)F.root.querySelector(restore)?.focus({preventScroll:true});}
  function show(config,push=false){if(!S.modal.length)S.origin={screen:F.screen,state:F.viewState,scroll:scrollY,focus:focusSelector(document.activeElement)};else if(push){const form=F.dialog.querySelector('#v38-manage-form');if(form)S.modal.at(-1).values=fieldData(form);}if(!push)S.modal=[];S.modal.push(config);drawModal();}
  function drawModal(){const c=S.modal.at(-1);if(!c)return;const body=typeof c.body==='function'?c.body():c.body;F.genericDialog(c.title,`<form id="v38-manage-form" data-submit="${c.action||''}" novalidate>${body}<p id="v38-manage-error" class="v38-manage-error" role="alert" hidden></p></form>`,c.label||'저장');F.dialog.classList.add('v38-manage-dialog');F.dialog.querySelector('.modal-head [data-action="close-modal"]').dataset.action='v38-manage-modal-cancel';F.dialog.querySelector('.modal-footer').innerHTML=c.action?`${b(S.modal.length>1?'돌아가기':'취소','modal-cancel')}<button type="submit" form="v38-manage-form" class="primary">${e(c.label||'저장')}</button>`:b(S.modal.length>1?'돌아가기':'닫기','modal-cancel');Object.entries(c.values||{}).forEach(([name,value])=>{const field=F.dialog.querySelector(`[name="${name}"]`);if(field)field.value=value;const choice=F.dialog.querySelector(`[data-name="${name}"] span`);if(choice)choice.textContent=value;});F.dialog.querySelector('input:not([type=hidden]):not([readonly]),textarea,.modal-footer button')?.focus({preventScroll:true});}
  function closeModal(all=false){if(S.modal.length>1&&!all){S.modal.pop();drawModal();return;}const origin=S.origin;S.modal=[];S.origin=null;old.close();if(origin){if(F.screen!==origin.screen)old.navigate(origin.screen,origin.state,true);window.scrollTo({top:origin.scroll,behavior:'instant'});if(origin.focus)F.root.querySelector(origin.focus)?.focus({preventScroll:true});}}
  function error(message,name){const p=F.dialog.querySelector('#v38-manage-error');if(!p)return;p.hidden=false;p.textContent=message;const control=F.dialog.querySelector(`[name="${name}"]`),target=control?.type==='hidden'?F.dialog.querySelector(`[data-name="${name}"]`):control;target?.setAttribute('aria-invalid','true');target?.setAttribute('aria-describedby',p.id);target?.focus();}
  function confirm(title,body,action,data,label){show({title,body:`<p class="v38-confirm-copy">${body}</p>`,action,data,label},S.modal.length>0);}
  function saveDone(){closeModal(true);if(['녹화 없음','예약 없음','장면 없음','운영자 없음','미션 없음','투표 없음','보상 없음','연결 없음'].includes(F.viewState)){F.viewState='기본';F.writeUrl(true);}refresh();}
  function findScene(){return S.scenes.find(scene=>scene.id===S.scene)||S.scenes[0];}
  const moderationBody=()=>{const d=S.moderationDraft;return section('채팅 설정',toggle('느린 채팅','slow',d.slow)+toggle('팔로워 전용','followers',d.followers)+toggle('링크 차단','links',d.links)+input('전송 간격 (초)','interval',d.interval,'type="number" min="1" max="120" data-v38-mod="interval"')+area('금칙어','banned',d.banned,'maxlength="1000" data-v38-mod="banned"')+`<div class="form-actions">${b('취소','moderation-reset',dirty()?'':'disabled')}${b('저장','moderation-save',dirty()?'':'disabled','primary')}</div>`);};
  let wasBroadcasting=F.broadcasting;
