    'metric-detail':()=>show({title:'지표 상세',body:F.dl([['표시 기간',S.metric.period],['수집 기준',new Date(S.metric.at).toLocaleString('ko-KR')],['마지막 정상 수집',new Date(S.metric.lastGoodAt||S.metric.at).toLocaleString('ko-KR')],['표시 상태',badge(S.metric.status)],['데이터 연결','운영 계측 연결 전']])+(S.metric.history||[]).slice(0,20).map(h=>`<p>${new Date(h.at).toLocaleTimeString('ko-KR')} ${e(h.status)}</p>`).join('')}),
    'policy-version':x=>F.openChoice(x,['2026-11-02','2026-10-01'],S.policyVersion,value=>{S.policyVersion=value;refresh();}),
